51 | @Command(name = "e2m", description = "Eclipse project to Maven project converter", version = "1.1.1", mixinStandardHelpOptions = true)
52 | public class Main implements Callable<Integer> {
53 | 
54 |     private static final Logger log = AppLogger.get(Main.class);
55 |     private static String e2mVersion;
56 | 
57 |     /** コマンドライン引数のコピー（デバッグ ZIP 用）。 */
58 |     private String[] rawArgs;
59 | 
60 |     @Option(names = {"-g", "--groupId"}, required = false, description = "Maven groupId of the output project")
61 |     private String groupId;
62 | 
63 |     @Option(names = {"-a", "--artifactId"}, required = false, description = "Maven artifactId of the output project")
64 |     private String artifactId;
65 | 
66 |     @Option(names = {"-v", "--artifactVersion"}, required = false, description = "Maven version of the output project (default: 1.0-SNAPSHOT)")
67 |     private String artifactVersion;
68 |     private static final String DEFAULT_ARTIFACT_VERSION = "1.0-SNAPSHOT";
69 | 
70 |     @Option(names = {"--javaTargetVersion"}, required = false, converter = JavaVersionConverter.class,
71 |             description = "Override maven.compiler.target in the generated pom.xml (default: taken from the Eclipse project settings)")
72 |     private JavaVersion javaTargetVersion;
73 | 
74 |     @Option(names = {"--convertToUtf8"}, description = "Convert source files to UTF-8 encoding during copy")
75 |     private boolean convertToUtf8;
76 | 
77 |     @Option(names = {"-e", "--sourceEncoding"}, required = false, description = "Source encoding of the input files (e.g. Shift_JIS). Required when --convertToUtf8 is specified.")
78 |     private String sourceEncoding;
79 | 
80 |     @Option(names = {"--debug"}, description = "Output debug information as e2m_debug_<datetime>.zip in the output directory")
81 |     private boolean debug;
82 | 
83 |     @Option(names = {"-n", "--noLiberty"}, description = "Do not add Liberty support (liberty-maven-plugin and server.xml) to the output project")
84 |     private boolean noLiberty;
85 | 
86 |     @Option(names = {"-w", "--addMavenWrapper"}, description = "Add Maven Wrapper files to the output project")
87 |     private boolean addMavenWrapper;
88 | 
89 |     @Parameters(index = "0", paramLabel = "<inputDir>", description = "Eclipse project directory to convert")
90 |     private File inputDir;
91 | 
92 |     @Parameters(index = "1", paramLabel = "<outputDir>", description = "Output directory for the Maven project")
93 |     private File outputDir;
94 | 
95 |     public static void main(String[] args) {
96 |         AppLogger.init();
97 |         Main main = new Main();
98 |         main.rawArgs = args.clone();
99 |         CommandLine command = new CommandLine(main);
100 |         e2mVersion = command.getCommandSpec().version()[0];
101 |         System.exit(command.execute(args));
102 |     }
