104 |     @Override
105 |     public Integer call() {
106 |         // --debug が指定された場合はファイルログを有効化（outputDir 配下に一時ファイルを作成）
107 |         if (debug) {
108 |             String timestamp = LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyyMMdd_HHmmss"));
109 |             Path logFilePath = outputDir.toPath().resolve("e2m_debug_" + timestamp + ".log");
110 |             AppLogger.enableDebug(logFilePath);
111 |             log.debug("デバッグモード有効: ログファイル={}", logFilePath);
112 |             log.debug("e2mバージョン={}", e2mVersion);
113 |         }
114 | 
115 |         Path eclipsePath = inputDir.toPath();
116 |         Path mavenPath = null; 
117 | 
118 |         // 引数の確認
119 |         if (!inputDir.isDirectory()) {
120 |             log.error(Messages.get("main.inputDirNotFound", inputDir));
121 |             return 1;
122 |         }
123 |         if (!eclipsePath.resolve(".project").toFile().exists()) {
124 |             log.error(Messages.get("main.notEclipseProject", inputDir));
125 |             return 1;
126 |         }
127 |         if (outputDir.exists() && !outputDir.isDirectory()) {
128 |             log.error(Messages.get("main.outputPathMustBeDirectory", outputDir));
129 |             return 1;
130 |         }
131 |         if (javaTargetVersion != null && javaTargetVersion.isUnknown()) {
132 |             log.error(Messages.get("main.invalidJavaTargetVersion", javaTargetVersion));
133 |             return 1;
134 |         }
135 | 
136 |         try {
137 |             // Step1. Eclipseプロジェクト情報をパース
138 |             log.info("");
139 |             log.info(Messages.get("main.step1"));
140 |             EclipseProject eclipseProject = EclipseProjectParser.parse(eclipsePath);
141 |             log.info(Messages.get("main.projectName", eclipseProject.projectName()));
142 |             log.info(Messages.get("main.projectType",
143 |                     eclipseProject.webProject() ? Messages.get("main.projectType.web") : Messages.get("main.projectType.java")));
144 |             log.info(Messages.get("main.javaSourceVersion", eclipseProject.javaSourceVersion()));
145 |             log.info(Messages.get("main.javaTargetVersion", eclipseProject.javaTargetVersion()));
146 |             if (eclipseProject.webProject()) {
147 |                 log.info(Messages.get("main.webVersion", eclipseProject.webVersion()));
148 |             }
149 |             log.info(Messages.get("main.sourceFolders", eclipseProject.sourceFolders()));
150 |             if (eclipseProject.webProject()) {
151 |                 log.info(Messages.get("main.webContentFolder", eclipseProject.webContentRoot()));
152 |             }
153 |             log.info(Messages.get("main.jarCount", eclipseProject.jarFiles().size()));
154 | 
155 |             if (eclipseProject.javaSourceVersion().isUnknown()) {
156 |                 log.error(Messages.get("main.unrecognizedJavaSourceVersion", eclipseProject.javaSourceVersion()));
157 |                 return 1;
158 |             }
159 | 
160 |             // Step2. 移行先のMavenプロジェクトの決定
161 |             log.info("");
162 |             log.info(Messages.get("main.step2"));
163 |             String defaultArtifactId = convertToArtifactId(eclipseProject.projectName());
164 |             if (groupId == null || groupId.isBlank()) {
165 |                 // オプション未指定の場合は対話的に入力を受け付ける
166 |                 try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
167 |                     log.debug("対話的入力モード開始");
168 |                     groupId = promptIfAbsent(reader, "groupId", groupId, null);
169 |                     artifactId = promptIfAbsent(reader, "artifactId", artifactId, defaultArtifactId);
170 |                     artifactVersion = promptIfAbsent(reader, "artifactVersion", artifactVersion, DEFAULT_ARTIFACT_VERSION);
171 |                     log.debug("groupId: {}", groupId);
172 |                     log.debug("artifactId: {}", artifactId);
173 |                     log.debug("version: {}", artifactVersion);
174 |                     // --convertToUtf8 未指定時は対話入力
175 |                     if (!convertToUtf8) {
176 |                         String answer = promptIfAbsent(reader,
177 |                             Messages.get("main.convertToUtf8"), null, "y/N").toLowerCase();
178 |                         convertToUtf8 = ("y".equals(answer) || "yes".equals(answer));
179 |                     }
180 |                     log.debug("convertToUtf8: {}", convertToUtf8);
181 |                     // --convertToUtf8 指定時は sourceEncoding も対話入力
182 |                     if (convertToUtf8) {
183 |                         sourceEncoding = promptIfAbsent(reader,
184 |                             Messages.get("main.sourceEncoding"), sourceEncoding, null);
185 |                         log.debug("sourceEncoding: {}", sourceEncoding);
186 |                     }
187 |                     if (eclipseProject.webProject() && !noLiberty) {
188 |                         String answer = promptIfAbsent(reader,
189 |                             Messages.get("main.addLiberty"), null, "Y/n").toLowerCase();
190 |                         noLiberty = ("n".equals(answer) || "no".equals(answer));
191 |                     }
192 |                     log.debug("noLiberty: {}", noLiberty);
193 |                     if (!addMavenWrapper) {
194 |                         String answer = promptIfAbsent(reader,
195 |                             Messages.get("main.addMavenWrapper"), null, "y/N").toLowerCase();
196 |                         addMavenWrapper = ("y".equals(answer) || "yes".equals(answer));
197 |                     }
198 |                     log.debug("addMavenWrapper: {}", addMavenWrapper);
199 |                 }
200 |             } else {
201 |                 // 少なくとも--groupIdが指定されていれば，あとは空ならデフォルトを使用する
202 |                 if (artifactId == null || artifactId.isBlank()) {
203 |                     artifactId = defaultArtifactId;
204 |                 }
205 |                 if (artifactVersion == null || artifactVersion.isBlank()) {
206 |                     artifactVersion = DEFAULT_ARTIFACT_VERSION;
207 |                 }
208 |                 log.info(Messages.get("main.groupId", groupId));
209 |                 log.info(Messages.get("main.artifactId", artifactId));
210 |                 log.info(Messages.get("main.version", artifactVersion));
211 |                 // --convertToUtf8 指定時は sourceEncoding も対話入力（--groupId 指定時で未指定の場合）
212 |                 if (convertToUtf8 && (sourceEncoding == null || sourceEncoding.isBlank())) {
213 |                     log.debug("対話的入力モード開始");
214 |                     try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
215 |                         sourceEncoding = promptIfAbsent(reader,
216 |                             Messages.get("main.sourceEncoding"), sourceEncoding, null);
217 |                     }
218 |                     log.debug("sourceEncoding: {}", sourceEncoding);
219 |                 }
220 |             }
221 | 
222 |             // --convertToUtf8 指定時の sourceEncoding バリデーション
223 |             Charset srcCharset = null;
224 |             if (convertToUtf8) {
225 |                 try {
226 |                     srcCharset = Charset.forName(sourceEncoding);
227 |                 } catch (Exception e) {
228 |                     log.error(Messages.get("main.invalidSourceEncoding", sourceEncoding));
229 |                     return 1;
230 |                 }
231 |             }
232 | 
233 |             // 出力先は outputDir/artifactId
234 |             mavenPath = outputDir.toPath().resolve(artifactId);
235 |             if (mavenPath.toFile().exists()) {
236 |                 log.error(Messages.get("main.outputDirAlreadyExists", mavenPath));
237 |                 return 1;
238 |             }
239 | 
240 |             log.info("");
241 |             log.info(Messages.get("main.conversionStart"));
242 |             log.info(Messages.get("main.input", eclipsePath.toAbsolutePath()));
243 |             log.info(Messages.get("main.output", mavenPath.toAbsolutePath()));
244 | 
245 |             // Step3. JAR依存関係を解決
246 |             log.info("");
247 |             log.info(Messages.get("main.step3"));
248 |             List<MavenDependency> dependencies = DependencyResolver.resolve(eclipseProject.jarFiles(), eclipsePath);
249 |             long found = dependencies.stream().filter(d -> !"system".equals(d.scope())).count();
250 |             long system = dependencies.stream().filter(d -> "system".equals(d.scope())).count();
251 |             log.info(Messages.get("main.foundDependencies", found));
252 |             log.info(Messages.get("main.systemDependencies", system));
253 | 
254 |             // Step4. pom.xml を生成
255 |             log.info("");
256 |             log.info(Messages.get("main.step4"));
257 |             // --javaTargetVersion が指定された場合はソースバージョンと比較してバリデーション
258 |             JavaVersion sourceVer = eclipseProject.javaSourceVersion();
259 |             if (javaTargetVersion != null) {
260 |                 if (!sourceVer.isUnknown() && javaTargetVersion.compareTo(sourceVer) < 0) {
261 |                     log.error(Messages.get("main.javaTargetLowerThanSource",
262 |                             javaTargetVersion, eclipseProject.javaSourceVersion()));
263 |                     return 1;
264 |                 }
265 |             }
266 |             // 実効 javaTargetVersion を確定（--javaTargetVersion 指定 > Eclipseプロジェクト設定）
267 |             JavaVersion effectiveTargetVersion = (javaTargetVersion != null && !javaTargetVersion.isUnknown())
268 |                     ? javaTargetVersion
269 |                     : eclipseProject.javaTargetVersion();
270 |             PomGenerator.generate(eclipseProject, dependencies, groupId, artifactId, artifactVersion,
271 |                     effectiveTargetVersion, convertToUtf8, noLiberty, mavenPath);
272 | 
273 |             // Step5. ソース・Webコンテンツをコピー
274 |             log.info("");
275 |             log.info(Messages.get("main.step5"));
276 |             if (convertToUtf8) {
277 |                 log.info(Messages.get("main.encodingConversionMode", sourceEncoding));
278 |             }
279 |             ProjectCopier.copy(eclipseProject, dependencies, eclipsePath, mavenPath,
280 |                     convertToUtf8, srcCharset, effectiveTargetVersion);
281 | 
282 |             // Liberty 対応: server.xml を生成（webProject かつ --noLiberty 未指定の場合のみ）
283 |             if (!noLiberty && eclipseProject.webProject()) {
284 |                 LibertyServerXmlGenerator.generate(eclipseProject, artifactId, mavenPath);
285 |             }
286 | 
287 |             // Step6. Maven Wrapper を追加（--addMavenWrapper 指定時のみ）
288 |             if (addMavenWrapper) {
289 |                 log.info("");
290 |                 log.info(Messages.get("main.step6"));
291 |                 MavenWrapperInstaller.install(mavenPath);
292 |             }
293 | 
294 |             log.info("");
295 |             log.info(Messages.get("main.conversionComplete"));
296 |             log.info(Messages.get("main.outputDir", mavenPath.toAbsolutePath()));
297 | 
298 |             return 0;
299 | 
300 |         } catch (Exception e) {
301 |             log.error(Messages.get("main.conversionError", e.getMessage()));
302 |             log.debug("スタックトレース:", e);
303 |             return 2;
304 |         } finally {
305 |             // --debug オプション: デバッグ ZIP を生成
306 |             if (debug) try {
307 |                 DebugArchiver.archive(eclipsePath, outputDir.toPath(), mavenPath, rawArgs);
308 |             } catch (IOException e) {
309 |                 e.printStackTrace();
310 |             }
311 |         }
312 |     }
313 | 
314 |     /**
315 |      * 引数が null または空の場合にプロンプトを表示して入力を受け付ける。
316 |      * デフォルト値がある場合は "[default]" 形式で表示し、空入力でデフォルト値を採用する。
317 |      *
318 |      * @param reader       入力ストリーム
319 |      * @param name         項目名（表示用）
320 |      * @param value        コマンドライン引数の値（null または空の場合にプロンプト表示）
321 |      * @param defaultValue デフォルト値（null の場合はデフォルトなし）
322 |      * @return 確定した値
323 |      */
324 |     private static String promptIfAbsent(BufferedReader reader, String name,
325 |             String value, String defaultValue) throws Exception {
326 |         if (value != null && !value.isBlank()) {
327 |             return value;
328 |         }
329 |         while (true) {
330 |             if (defaultValue != null) {
331 |                 System.out.print(Messages.get("main.prompt.withDefault", name, defaultValue));
332 |             } else {
333 |                 System.out.print(Messages.get("main.prompt.withoutDefault", name));
334 |             }
335 |             System.out.flush();
336 |             String line = reader.readLine();
337 |             if (line == null) {
338 |                 // EOF（パイプ等）の場合はデフォルト値を使用
339 |                 return defaultValue != null ? defaultValue : "";
340 |             }
341 |             String trimmed = line.trim();
342 |             if (trimmed.isEmpty()) {
343 |                 if (defaultValue != null) {
344 |                     return defaultValue;
345 |                 }
346 |                 // 対話的入力モードでのメッセージは，ロガーを使わず，直接System.outに出力
347 |                 System.out.print(Messages.get("main.prompt.enterValue"));
348 |                 continue;
349 |             }
350 |             return trimmed;
351 |         }
352 |     }
353 | 
354 |     // artifactIdとして許可する文字（半角英数字、ハイフン、アンダースコア）以外にマッチする正規表現
355 |     private static final Pattern INVALID_CHARS = Pattern.compile("[^a-z0-9\\-_]");
356 | 
357 |     // キャメルケースの境界（大文字の前）にマッチする正規表現
358 |     private static final Pattern CAMEL_CASE_BOUNDARY = Pattern.compile("(?<=[a-z0-9])(?=[A-Z])");
359 | 
360 |     /**
361 |      * プロジェクト名からMavenのartifactIdとして利用可能な文字列を生成します。
362 |      *
363 |      * @param projectName プロジェクト名
364 |      * @return artifactId用文字列
365 |      */
366 |     public static String convertToArtifactId(String projectName) {
367 |         if (projectName == null || projectName.isBlank()) {
368 |             return "default-artifact";
369 |         }
370 | 
371 |         // 1. パッケージ名が含まれている場合（完全限定名）、最後のクラス名部分だけを抽出
372 |         String simpleName = projectName.substring(projectName.lastIndexOf('.') + 1);
373 | 
374 |         // 2. キャメルケース（OrderManager -> Order-Manager）をハイフン区切りに変換
375 |         String kebabCase = CAMEL_CASE_BOUNDARY.matcher(simpleName).replaceAll("-");
376 | 
377 |         // 3. すべて小文字に変換
378 |         String lowerCase = kebabCase.toLowerCase();
379 | 
380 |         // 4. artifactIdとして使えない文字（日本語や特殊記号など）を完全に除去
381 |         String sanitized = INVALID_CHARS.matcher(lowerCase).replaceAll("");
382 | 
383 |         // 5. 連続したハイフンやアンダースコアを綺麗に整理
384 |         sanitized = sanitized.replaceAll("[-_]{2,}", "-");
385 | 
386 |         // 6. 先頭や末尾にあるハイフン・アンダースコアを除去
387 |         sanitized = sanitized.replaceAll("^[-_]+|[-_]+$", "");
388 | 
389 |         // すべての文字が削られて空になった場合のフォールバック
390 |         return sanitized.isBlank() ? "converted-artifact" : sanitized;
391 |     }
392 | 
393 |     /**
394 |      * picocli 用の {@link JavaVersion} 型変換クラス。
395 |      * 変換に失敗した場合は {@link JavaVersion#UNKNOWN_VERSION} を返す。
396 |      */
397 |     static class JavaVersionConverter implements ITypeConverter<JavaVersion> {
398 |         @Override
399 |         public JavaVersion convert(String value) {
400 |             return JavaVersion.of(value);
401 |         }
402 |     }
403 | }
