5 | import java.util.ResourceBundle;
6 | 
7 | public final class Messages {
8 | 
9 |     private static final String BUNDLE_NAME = "messages";
10 |     private static final Locale ENGLISH = Locale.ENGLISH;
11 | 
12 |     private Messages() {
13 |     }
14 | 
15 |     public static String get(String key, Object... args) {
16 |         String pattern = bundle().getString(key);
17 |         if (args.length == 0) {
18 |             return pattern;
19 |         }
20 |         return MessageFormat.format(pattern, args);
21 |     }
22 | 
23 |     public static String localeName() {
24 |         return isJapanese() ? "ja" : "en";
25 |     }
26 | 
27 |     private static ResourceBundle bundle() {
28 |         Locale locale = isJapanese() ? Locale.JAPANESE : ENGLISH;
29 |         return ResourceBundle.getBundle(BUNDLE_NAME, locale);
30 |     }
31 | 
32 |     private static boolean isJapanese() {
33 |         return Locale.JAPANESE.getLanguage().equals(defaultLocale().getLanguage());
34 |     }
35 | 
36 |     private static Locale defaultLocale() {
37 |         Locale locale = Locale.getDefault();
38 |         if (locale == null) {
39 |             return ENGLISH;
40 |         }
41 |         return locale;
42 |     }
43 | }
