39 |     /** コンソールアペンダーのパターン（メッセージのみ）。 */
40 |     private static final String CONSOLE_PATTERN = "%msg%n";
41 | 
42 |     /** ファイルアペンダーのパターン（タイムスタンプ+レベル+メッセージ）。 */
43 |     private static final String FILE_PATTERN = "%date{yyyy-MM-dd HH:mm:ss.SSS} %-5level %msg%n";
