45 | /**
46 |  * Eclipseの.classpathに記載されたJARファイルのSHA1ハッシュを計算し、
47 |  * Maven Central REST APIで依存関係情報を検索するクラス。
48 |  */
49 | public class DependencyResolver {
50 | 
51 |     private static final Logger log = AppLogger.get(DependencyResolver.class);
52 | 
53 |     private static final String MAVEN_SEARCH_URL =
54 |             "https://search.maven.org/solrsearch/select?q=1:%s&rows=1&wt=json";
55 | 
56 | 
57 |     private final HttpClient httpClient;
58 | 
59 |     public DependencyResolver() {
60 |         this.httpClient = HttpClient.newBuilder()
61 |                 .connectTimeout(Duration.ofSeconds(10))
62 |                 .sslContext(createTrustAllSslContext())
63 |                 .build();
64 |     }
65 | 
66 |     /**
67 |      * SSLインスペクション環境向けに、証明書検証を行わないSSLContextを生成する。
68 |      */
69 |     private static SSLContext createTrustAllSslContext() {
70 |         TrustManager[] trustAll = new TrustManager[]{
71 |             new X509TrustManager() {
72 |                 @Override public void checkClientTrusted(X509Certificate[] chain, String authType) {}
73 |                 @Override public void checkServerTrusted(X509Certificate[] chain, String authType) {
74 |                     if (log.isDebugEnabled() && chain != null) {
75 |                         log.debug("  SSLチェックは省略されます");
76 |                         for (X509Certificate cert : chain) {
77 |                             log.debug("  Server certificate: subject={}, issuer={}, notBefore={}, notAfter={}",
78 |                                     cert.getSubjectX500Principal(),
79 |                                     cert.getIssuerX500Principal(),
80 |                                     cert.getNotBefore(),
81 |                                     cert.getNotAfter());
82 |                         }
83 |                     }
84 |                 }
85 |                 @Override public X509Certificate[] getAcceptedIssuers() { return new X509Certificate[0]; }
86 |             }
87 |         };
88 |         try {
89 |             SSLContext ctx = SSLContext.getInstance("TLS");
90 |             ctx.init(null, trustAll, new java.security.SecureRandom());
91 |             return ctx;
92 |         } catch (NoSuchAlgorithmException | KeyManagementException e) {
93 |             throw new IllegalStateException(Messages.get("dependency.sslcontext.initerr"), e);
94 |         }
95 |     }
96 | 
97 |     /**
98 |      * {@link JarFile} のリストを受け取り、Maven依存関係リストに解決して返す。
99 |      *
100 |      * @param jarFiles Eclipseの.classpathから構築した {@link JarFile} のリスト
101 |      * @param inputDir Eclipseプロジェクトのルートディレクトリ（相対パス解決の基準）
102 |      * @return 解決済みの {@link MavenDependency} リスト
103 |      */
104 |     public static List<MavenDependency> resolve(List<JarFile> jarFiles, Path inputDir) {
105 |         DependencyResolver resolver = new DependencyResolver();
106 |         List<MavenDependency> results = new ArrayList<>();
107 |         for (JarFile jarFile : jarFiles) {
108 |             results.add(resolver.resolveJar(jarFile, inputDir));
109 |         }
110 |         return results;
111 |     }
112 | 
113 |     /**
114 |      * 1つの {@link JarFile} を解決する。
115 |      *
116 |      * <p>スコープは {@link JarFile} の {@code test} / {@code exported} 属性から決定する：</p>
117 |      * <ul>
118 |      *   <li>{@code test=true} → Maven {@code test} スコープ</li>
119 |      *   <li>{@code exported=true} → Maven compile スコープ（scope要素なし）</li>
120 |      *   <li>それ以外 → Maven {@code provided} スコープ</li>
121 |      * </ul>
122 |      *
123 |      * @param jarFile  解決対象の {@link JarFile}
124 |      * @param inputDir Eclipseプロジェクトのルートディレクトリ
125 |      * @return 解決済みの {@link MavenDependency}
126 |      */
127 |     private MavenDependency resolveJar(JarFile jarFile, Path inputDir) {
128 |         String jarPath = jarFile.path();
129 |         // JarFile の属性からスコープを決定する
130 |         final String scope;
131 |         if (jarFile.test()) {
132 |             scope = "test";
133 |         } else if (jarFile.exported()) {
134 |             scope = null; // compile (Maven デフォルト)
135 |         } else {
136 |             scope = "provided";
137 |         }
138 |         Path path = Path.of(jarPath).isAbsolute()
139 |                 ? Path.of(jarPath)
140 |                 : inputDir.resolve(jarPath);
141 | 
142 |         String jarFileName = path.getFileName().toString();
143 |         // 拡張子なしのベース名
144 |         String baseName = jarFileName.endsWith(".jar")
145 |                 ? jarFileName.substring(0, jarFileName.length() - 4)
146 |                 : jarFileName;
147 | 
148 |         log.info(Messages.get("dependency.resolving", jarFileName));
149 | 
150 |         if (!Files.exists(path)) {
151 |             log.warn(Messages.get("dependency.jarNotFound", path));
152 |             log.info(Messages.get("dependency.notFoundSystemScope", jarFileName));
153 |             return new MavenDependency(baseName, baseName, "0.0.0", "system", jarPath, jarFile.exported());
154 |         }
155 | 
156 |         String sha1;
157 |         try {
158 |             sha1 = FileUtils.computeSha1(path);
159 |             log.debug("    SHA: {}", sha1);
160 |         } catch (Exception e) {
161 |             log.error(Messages.get("dependency.sha1CalculationFailed", path, e.getMessage()));
162 |             log.info(Messages.get("dependency.sha1ErrorSystemScope", jarFileName));
163 |             return new MavenDependency(baseName, baseName, "0.0.0", "system", path.toAbsolutePath().toString(), jarFile.exported());
164 |         }
165 | 
166 |         try {
167 |             String json = callMavenCentralApi(sha1);
168 |             log.debug("    JSON Response: {}", json);
169 |             return parseResponse(json, baseName, path.toAbsolutePath().toString(), scope, jarFile.exported());
170 |         } catch (Exception e) {
171 |             log.error(Messages.get("dependency.mavenCentralApiFailed", jarFileName, e.getMessage()));
172 |             throw new RuntimeException("Maven Central API call failed: " + jarFileName, e);
173 |         }
174 |     }
175 | 
176 |     /**
177 |      * Maven Central Search APIを呼び出してJSONレスポンスを返す。
178 |      * テスト用にprotectedとして定義し、サブクラスでオーバーライド可能にする。
179 |      */
180 |     protected String callMavenCentralApi(String sha1) throws IOException, InterruptedException {
181 |         String url = String.format(MAVEN_SEARCH_URL, sha1);
182 |         HttpRequest request = HttpRequest.newBuilder()
183 |                 .uri(URI.create(url))
184 |                 .timeout(Duration.ofSeconds(60))
185 |                 .GET()
186 |                 .build();
187 |         HttpResponse<String> response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
188 |         return response.body();
189 |     }
190 | 
191 |     // private static final Pattern GROUP_ID_PATTERN    = Pattern.compile("\"g\"\\s*:\\s*\"([^\"]+)\"");
192 |     // private static final Pattern ARTIFACT_ID_PATTERN = Pattern.compile("\"a\"\\s*:\\s*\"([^\"]+)\"");
193 |     // private static final Pattern VERSION_PATTERN     = Pattern.compile("\"latestVersion\"\\s*:\\s*\"([^\"]+)\"");
194 |     // private static final Pattern NUM_FOUND_PATTERN   = Pattern.compile("\"numFound\"\\s*:\\s*(\\d+)");
195 |     private static final Pattern GROUP_ID_PATTERN    = Pattern.compile("\"g\":\"([^\"]+)\"");
196 |     private static final Pattern ARTIFACT_ID_PATTERN = Pattern.compile("\"a\":\"([^\"]+)\"");
197 |     private static final Pattern VERSION_PATTERN     = Pattern.compile("\"v\":\"([^\"]+)\"");
198 |     private static final Pattern NUM_FOUND_PATTERN   = Pattern.compile("\"numFound\"\\s*:\\s*(\\d+)");
199 | 
200 |     /**
201 |      * Maven Central APIのJSONレスポンスをパースしてMavenDependencyを返す。
202 |      *
203 |      * <p>Maven Central で見つかった場合のスコープは {@code scope} をそのまま使う。
204 |      * 見つからなかった場合（system スコープ）は {@code exported} を MavenDependency にコピーする。</p>
205 |      */
206 |     private static MavenDependency parseResponse(String json, String baseName,
207 |                                                  String absolutePath, String scope, boolean exported) {
208 |         // numFound:0 なら見つからなかった
209 |         Matcher numFoundMatcher = NUM_FOUND_PATTERN.matcher(json);
210 |         if (numFoundMatcher.find()) {
211 |             int numFound = Integer.parseInt(numFoundMatcher.group(1));
212 |             if (numFound == 0) {
213 |                 log.info(Messages.get("dependency.notFoundInMavenCentral", baseName));
214 |                 return new MavenDependency(baseName, baseName, "0.0.0", "system", absolutePath, exported);
215 |             }
216 |         }
217 | 
218 |         Matcher gMatcher = GROUP_ID_PATTERN.matcher(json);
219 |         Matcher aMatcher = ARTIFACT_ID_PATTERN.matcher(json);
220 |         Matcher vMatcher = VERSION_PATTERN.matcher(json);
221 | 
222 |         if (gMatcher.find() && aMatcher.find() && vMatcher.find()) {
223 |             String groupId    = gMatcher.group(1);
224 |             String artifactId = aMatcher.group(1);
225 |             String version    = vMatcher.group(1);
226 |             log.info(Messages.get("dependency.found", groupId, artifactId, version));
227 |             return new MavenDependency(groupId, artifactId, version, scope, null);
228 |         }
229 | 
230 |         // パースに失敗した場合もsystemスコープ
231 |         log.warn(Messages.get("dependency.parseFailed", baseName));
232 |         log.info(Messages.get("dependency.parseErrorSystemScope", baseName));
233 |         return new MavenDependency(baseName, baseName, "0.0.0", "system", absolutePath, exported);
234 |     }
235 | }
