17 | package com.ibm.jp.automation.e2m.spec;
18 | 
19 | import java.util.HashMap;
20 | 
21 | /**
22 |  * Javaのバージョン番号を表す不変クラス。
23 |  *
24 |  * <p>以下の形式の文字列からインスタンスを生成できる。</p>
25 |  * <ul>
26 |  *   <li>{@code "1.1"} 〜 {@code "1.8"} — Java 1〜8 を表す旧形式</li>
27 |  *   <li>{@code "5"} 〜 それ以降の整数 — Java 5 以降の新形式</li>
28 |  * </ul>
29 |  *
30 |  * <p>認識できない文字列が渡された場合は {@link #UNKNOWN_VERSION} を返す。
31 |  * {@code UNKNOWN_VERSION} は内部値 {@code -1} を持ち、全ての有効なバージョンより古い扱いになる。</p>
32 |  *
33 |  * <p>{@link Comparable} を実装しており、バージョンの大小比較が可能。</p>
34 |  */
35 | public final class JavaVersion implements Comparable<JavaVersion> {
36 | 
37 |     /**
38 |      * 認識できないバージョン文字列を表す特殊インスタンス。
39 |      * 内部値は {@code -1} であり、全ての有効な {@link JavaVersion} より小さい。
40 |      */
41 |     private static final int UNKNOWN_VERSION = -1;
42 | 
43 |     /**
44 |      * 有効なJavaVersionについては，シングルインスタンスを返す。
45 |      * なので，{@code if (version == JavaVersion.Java8)}などの比較が可能。
46 |      */
47 |     public static final JavaVersion Java8 = new JavaVersion(8, "1.8");
48 |     public static final JavaVersion Java9 = new JavaVersion(9, "9");
49 |     private static HashMap<Integer,JavaVersion> cache;
50 |     static {
51 |         cache = new HashMap<>();
52 |         cache.put(8, Java8);
53 |         cache.put(9, Java9);
54 |     }
55 |     private static JavaVersion getCache(int version) {
56 |         JavaVersion ret = cache.get(version);
57 |         if (ret != null) {
58 |             return ret;
59 |         } else {
60 |             if (version <= 8) {
61 |                 ret = new JavaVersion(version, "1." + Integer.toString(version));
62 |             } else {
63 |                 ret = new JavaVersion(version, Integer.toString(version));
64 |             }
65 |             cache.put(version, ret);
66 |             return ret;
67 |         }
68 |     }
69 | 
70 |     /** 内部的に保持する整数バージョン番号（例: 1.8 → 8、17 → 17。UNKNOWN は -1）。 */
71 |     private final int value;
72 | 
73 |     /** 元の文字列表現（toString() で返す）。 */
74 |     private final String original;
75 | 
76 |     private JavaVersion(int value, String original) {
77 |         this.value = value;
78 |         this.original = original;
79 |     }
80 | 
81 |     /**
82 |      * バージョン文字列から {@link JavaVersion} インスタンスを生成する。
83 |      *
84 |      * <p>受け付ける形式:</p>
85 |      * <ul>
86 |      *   <li>{@code "1.0"} 〜 {@code "1.8"} — Java 1〜8（旧形式）</li>
87 |      *   <li>{@code "5"} 以上の整数文字列 — Java 5 以降（新形式）</li>
88 |      * </ul>
89 |      *
90 |      * <p>認識できない文字列（null・空文字・不正な形式・負数）が渡された場合は、
91 |      * その文字列を {@code original} として保持する {@link #isUnknown()} が {@code true} を返す
92 |      * インスタンスを生成して返す。null の場合は {@code original} に {@code "null"} を使用する。</p>
93 |      *
94 |      * @param version バージョン文字列
95 |      * @return 対応する {@link JavaVersion} インスタンス。認識できない場合は {@code isUnknown() == true} のインスタンス
96 |      */
97 |     public static JavaVersion of(String version) {
98 |         if (version == null || version.isBlank()) {
99 |             return new JavaVersion(UNKNOWN_VERSION, version == null ? "null" : version.trim());
100 |         }
101 |         String v = version.trim();
102 | 
103 |         // "1.x" 形式（例: "1.8"）
104 |         if (v.startsWith("1.")) {
105 |             try {
106 |                 int minor = Integer.parseInt(v.substring(2));
107 |                 if (minor < 0 || minor > 8) {
108 |                     return new JavaVersion(UNKNOWN_VERSION, v);
109 |                 }
110 |                 return getCache(minor);
111 |             } catch (NumberFormatException e) {
112 |                 return new JavaVersion(UNKNOWN_VERSION, v);
113 |             }
114 |         }
115 | 
116 |         // 整数形式（例: "5", "11", "17"）
117 |         try {
118 |             int n = Integer.parseInt(v);
119 |             if (n < 5) {
120 |                 return new JavaVersion(UNKNOWN_VERSION, v);
121 |             }
122 |             return getCache(n);
123 |         } catch (NumberFormatException e) {
124 |             return new JavaVersion(UNKNOWN_VERSION, v);
125 |         }
126 |     }
127 | 
128 |     /**
129 |      * このインスタンスが {@link #UNKNOWN_VERSION} かどうかを返す。
130 |      */
131 |     public boolean isUnknown() {
132 |         return this.value == UNKNOWN_VERSION;
133 |     }
134 | 
135 |     /**
136 |      * 内部的な整数バージョン番号を返す（例: "1.8" → 8、"17" → 17）。
137 |      */
138 |     public int toInt() {
139 |         return value;
140 |     }
141 | 
142 |     @Override
143 |     public int compareTo(JavaVersion other) {
144 |         return Integer.compare(this.value, other.value);
145 |     }
146 | 
147 |     @Override
148 |     public boolean equals(Object obj) {
149 |         if (this == obj) return true;
150 |         if (!(obj instanceof JavaVersion other)) return false;
151 |         return this.value == other.value;
152 |     }
153 | 
154 |     @Override
155 |     public int hashCode() {
156 |         return Integer.hashCode(value);
157 |     }
158 | 
159 |     /** 元の文字列表現を返す（例: {@code "1.8"}、{@code "17"}）。 */
160 |     @Override
161 |     public String toString() {
162 |         return original;
163 |     }
164 | }
