210 |     /**
211 |      * DependencyResolverのprivateなresolveJarメソッドを
212 |      * スタブインスタンス経由で呼び出すヘルパー。
213 |      * <p>
214 |      * staticのresolve()は内部でnew DependencyResolver()するため、
215 |      * スタブを注入できない。そのためリフレクションで非公開メソッドを直接呼ぶ。
216 |      */
217 |     private static List<MavenDependency> invokeResolveViaReflection(
218 |             DependencyResolver resolver, List<String> jarPaths, Path inputDir) {
219 |         try {
220 |             var method = DependencyResolver.class.getDeclaredMethod(
221 |                     "resolveJar", JarFile.class, Path.class);
222 |             method.setAccessible(true);
223 |             List<MavenDependency> results = new java.util.ArrayList<>();
224 |             for (String jarPath : jarPaths) {
225 |                 results.add((MavenDependency) method.invoke(
226 |                         resolver, new JarFile(jarPath, false, true), inputDir));
227 |             }
228 |             return results;
229 |         } catch (Exception e) {
230 |             throw new RuntimeException("リフレクション呼び出しに失敗: " + e.getMessage(), e);
231 |         }
232 |     }
233 | }
