40 | /**
41 |  * EclipseProject情報と依存関係リストからMavenのpom.xmlを生成するクラス。
42 |  */
43 | public class PomGenerator {
44 | 
45 |     private static final Logger log = AppLogger.get(PomGenerator.class);
46 | 
47 |     private static final String MAVEN_COMPILER_PLUGIN_VERSION = "3.15.0";
48 |     private static final String MAVEN_WAR_PLUGIN_VERSION = "3.5.1";
49 |     private static final String NATIVE2ASCII_PLUGIN_VERSION = "2.1.1";
50 |     private static final String LIBERTY_MAVEN_PLUGIN_VERSION = "3.12.0";
51 | 
52 |     private PomGenerator() {}
53 | 
54 |     /**
55 |      * pom.xmlを生成して出力ディレクトリに保存する。
56 |      *
57 |      * @param eclipseProject        パース済みEclipseプロジェクト情報
58 |      * @param dependencies          解決済み依存関係リスト
59 |      * @param groupId               生成するpom.xmlのgroupId
60 |      * @param artifactId            生成するpom.xmlのartifactId
61 |      * @param version               生成するpom.xmlのversion
62 |      * @param effectiveTargetVersion maven.compiler.targetに使用するJavaバージョン。
63 |      * @param convertToUtf8      --convert-to-utf8 オプションが指定されているか
64 |      * @param outputDir          出力ディレクトリ
65 |      * @throws Exception XML生成またはファイル書き込みに失敗した場合
66 |      */
67 |     public static void generate(
68 |             EclipseProject eclipseProject,
69 |             List<MavenDependency> dependencies,
70 |             String groupId,
71 |             String artifactId,
72 |             String version,
73 |             JavaVersion effectiveTargetVersion,
74 |             boolean convertToUtf8,
75 |             boolean noLiberty,
76 |             Path outputDir) throws Exception {
77 | 
78 |         log.debug("  generate開始");
79 |         DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
80 |         DocumentBuilder db = dbf.newDocumentBuilder();
81 |         Document doc = db.newDocument();
82 | 
83 |         // <project>
84 |         Element project = doc.createElement("project");
85 |         project.setAttribute("xmlns", "http://maven.apache.org/POM/4.0.0");
86 |         project.setAttribute("xmlns:xsi", "http://www.w3.org/2001/XMLSchema-instance");
87 |         project.setAttribute("xsi:schemaLocation",
88 |                 "http://maven.apache.org/POM/4.0.0 http://maven.apache.org/xsd/maven-4.0.0.xsd");
89 |         doc.appendChild(project);
90 | 
91 |         addTextElement(doc, project, "modelVersion", "4.0.0");
92 |         addTextElement(doc, project, "groupId", groupId);
93 |         addTextElement(doc, project, "artifactId", artifactId);
94 |         addTextElement(doc, project, "version", version);
95 | 
96 |         if (eclipseProject.webProject()) {
97 |             log.debug("  packaging: war");
98 |             addTextElement(doc, project, "packaging", "war");
99 |         }
100 | 
101 |         // <properties>
102 |         JavaVersion javaSourceVersion = eclipseProject.javaSourceVersion();
103 |         JavaVersion javaTargetVersion = effectiveTargetVersion;
104 |         Element properties = doc.createElement("properties");
105 |         if (!convertToUtf8) {
106 |             properties.appendChild(doc.createComment(Messages.get("pom.sourceEncodingNotice")));
107 |         }
108 |         addTextElement(doc, properties, "project.build.sourceEncoding", "UTF-8");
109 |         addTextElement(doc, properties, "maven.compiler.source", javaSourceVersion.toString());
110 |         addTextElement(doc, properties, "maven.compiler.target", javaTargetVersion.toString());
111 |         project.appendChild(properties);
112 | 
113 |         // <dependencies>
114 |         boolean hasDependencies = !dependencies.isEmpty() || eclipseProject.webProject();
115 |         // libs/compile に JAR があるか（system スコープかつ exported=true）を判定
116 |         boolean hasCompileLibs = dependencies.stream()
117 |                 .anyMatch(d -> "system".equals(d.scope()) && d.exported());
118 |         if (hasDependencies) {
119 |             Element deps = doc.createElement("dependencies");
120 |             for (MavenDependency dep : dependencies) {
121 |                 Element dependency = doc.createElement("dependency");
122 |                 addTextElement(doc, dependency, "groupId", dep.groupId());
123 |                 addTextElement(doc, dependency, "artifactId", dep.artifactId());
124 |                 addTextElement(doc, dependency, "version", dep.version());
125 |                 if (dep.scope() != null && !dep.scope().isEmpty()) {
126 |                     addTextElement(doc, dependency, "scope", dep.scope());
127 |                 }
128 |                 if (dep.systemPath() != null) {
129 |                     // system スコープの JAR は libs/compile または libs/provided にコピーされる
130 |                     String fileName = Path.of(dep.systemPath()).getFileName().toString();
131 |                     String subDir = dep.exported() ? "libs/compile" : "libs/provided";
132 |                     addTextElement(doc, dependency, "systemPath",
133 |                             "${project.basedir}/" + subDir + "/" + fileName);
134 |                 }
135 |                 deps.appendChild(dependency);
136 |             }
137 |             // webProject の場合は Java EE / Jakarta EE API を provided で追加
138 |             if (eclipseProject.webProject() && eclipseProject.webVersion() != null) {
139 |                 String webVersion = eclipseProject.webVersion();
140 |                 boolean tooOld = webVersion.startsWith("2");
141 |                 String resolvedVersion = tooOld ? "3.0" : webVersion;
142 |                 JavaEEVersion javaEE = JavaEEVersion.fromWebVersion(resolvedVersion);
143 |                 Element dependency = doc.createElement("dependency");
144 |                 if (tooOld) {
145 |                     log.debug("  Web APIのバージョン {} は古すぎるため、3.0に置き換えて依存関係を追加", webVersion);
146 |                     deps.appendChild(doc.createComment(
147 |                             Messages.get("pom.legacyServletWarning", webVersion)));
148 |                 }
149 |                 addTextElement(doc, dependency, "groupId", javaEE.getGroupId());
150 |                 addTextElement(doc, dependency, "artifactId", javaEE.getArtifactId());
151 |                 addTextElement(doc, dependency, "version", javaEE.getVersion());
152 |                 addTextElement(doc, dependency, "scope", "provided");
153 |                 deps.appendChild(dependency);
154 |             }
155 |             project.appendChild(deps);
156 |         }
157 | 
158 |         // <build><plugins><plugin> maven-compiler-plugin
159 |         Element build = doc.createElement("build");
160 |         addTextElement(doc, build, "finalName", artifactId);
161 |         Element plugins = doc.createElement("plugins");
162 |         Element compilerPlugin = doc.createElement("plugin");
163 |         addTextElement(doc, compilerPlugin, "groupId", "org.apache.maven.plugins");
164 |         addTextElement(doc, compilerPlugin, "artifactId", "maven-compiler-plugin");
165 |         addTextElement(doc, compilerPlugin, "version", MAVEN_COMPILER_PLUGIN_VERSION);
166 |         plugins.appendChild(compilerPlugin);
167 |         // webProject の場合は maven-war-plugin を追加
168 |         if (eclipseProject.webProject()) {
169 |             Element warPlugin = doc.createElement("plugin");
170 |             addTextElement(doc, warPlugin, "groupId", "org.apache.maven.plugins");
171 |             addTextElement(doc, warPlugin, "artifactId", "maven-war-plugin");
172 |             addTextElement(doc, warPlugin, "version", MAVEN_WAR_PLUGIN_VERSION);
173 |             Element configuration = doc.createElement("configuration");
174 |             addTextElement(doc, configuration, "failOnMissingWebXml", "false");
175 |             // libs/compile に JAR がある場合は WEB-INF/lib へコピーする webResources 設定を追加
176 |             if (hasCompileLibs) {
177 |                 log.debug("  ${project.basedir}/libs/compile以下のJARファイルをコピーするようmaven-war-pluginを構成");
178 |                 Element webResources = doc.createElement("webResources");
179 |                 Element resource = doc.createElement("resource");
180 |                 addTextElement(doc, resource, "directory", "${project.basedir}/libs/compile");
181 |                 addTextElement(doc, resource, "targetPath", "WEB-INF/lib");
182 |                 Element includes = doc.createElement("includes");
183 |                 addTextElement(doc, includes, "include", "*.jar");
184 |                 resource.appendChild(includes);
185 |                 webResources.appendChild(resource);
186 |                 configuration.appendChild(webResources);
187 |             }
188 |             warPlugin.appendChild(configuration);
189 |             plugins.appendChild(warPlugin);
190 |             // Liberty 対応: --noLiberty 未指定の場合は liberty-maven-plugin を追加
191 |             if (!noLiberty) {
192 |                 Element libertyPlugin = doc.createElement("plugin");
193 |                 addTextElement(doc, libertyPlugin, "groupId", "io.openliberty.tools");
194 |                 addTextElement(doc, libertyPlugin, "artifactId", "liberty-maven-plugin");
195 |                 addTextElement(doc, libertyPlugin, "version", LIBERTY_MAVEN_PLUGIN_VERSION);
196 |                 plugins.appendChild(libertyPlugin);
197 |             }
198 |         }
199 |         // --convert-to-utf8 かつ javaTargetVersion <= 8 の場合は native2ascii-maven-plugin を追加
200 |         // javaTargetVersion は 93-96 行で確定済み（javaTargetOverride 優先）
201 |         if (convertToUtf8 && !javaTargetVersion.isUnknown()
202 |                 && javaTargetVersion.compareTo(JavaVersion.Java8) <= 0) {
203 |             Element n2aPlugin = doc.createElement("plugin");
204 |             addTextElement(doc, n2aPlugin, "groupId", "org.codehaus.mojo");
205 |             addTextElement(doc, n2aPlugin, "artifactId", "native2ascii-maven-plugin");
206 |             addTextElement(doc, n2aPlugin, "version", NATIVE2ASCII_PLUGIN_VERSION);
207 |             Element executions = doc.createElement("executions");
208 |             Element execution = doc.createElement("execution");
209 |             addTextElement(doc, execution, "id", "native2ascii-utf8-resources");
210 |             addTextElement(doc, execution, "phase", "process-resources");
211 |             Element goals = doc.createElement("goals");
212 |             addTextElement(doc, goals, "goal", "resources");
213 |             execution.appendChild(goals);
214 |             Element configuration = doc.createElement("configuration");
215 |             addTextElement(doc, configuration, "encoding", "UTF-8");
216 |             addTextElement(doc, configuration, "srcDir", "${project.basedir}/src/main/resources-utf8");
217 |             addTextElement(doc, configuration, "outputDir", "${project.build.outputDirectory}");
218 |             execution.appendChild(configuration);
219 |             executions.appendChild(execution);
220 |             n2aPlugin.appendChild(executions);
221 |             plugins.appendChild(n2aPlugin);
222 |         }
223 |         build.appendChild(plugins);
224 |         project.appendChild(build);
225 | 
226 |         // XMLをファイルに書き出す
227 |         Files.createDirectories(outputDir);
228 |         TransformerFactory tf = TransformerFactory.newInstance();
229 |         Transformer transformer = tf.newTransformer();
230 |         transformer.setOutputProperty(OutputKeys.INDENT, "yes");
231 |         transformer.setOutputProperty(OutputKeys.ENCODING, "UTF-8");
232 |         transformer.setOutputProperty("{http://xml.apache.org/xslt}indent-amount", "2");
233 | 
234 |         Path pomPath = outputDir.resolve("pom.xml");
235 |         transformer.transform(new DOMSource(doc), new StreamResult(pomPath.toFile()));
236 | 
237 |         log.info(Messages.get("pom.generated", pomPath));
238 |     }
239 | 
240 |     private static void addTextElement(Document doc, Element parent, String tagName, String text) {
241 |         Element el = doc.createElement(tagName);
242 |         el.appendChild(doc.createTextNode(text));
243 |         parent.appendChild(el);
244 |     }
245 | }
