17 | package com.ibm.jp.automation.e2m.spec;
18 | 
19 | /**
20 |  * Java EE / Jakarta EE 仕様のバージョン情報を保持するクラス。
21 |  * Servlet 仕様のバージョン（{@code jst.web} ファセットの version）から
22 |  * pom.xml に出力すべき {@code <dependency>} 情報を提供する。
23 |  *
24 |  * <p>使用例:
25 |  * <pre>
26 |  *   JavaEEVersion v = JavaEEVersion.of("3.0");
27 |  *   v.getGroupId();    // "javax"
28 |  *   v.getArtifactId(); // "javaee-api"
29 |  *   v.getVersion();    // "6.0"
30 |  * </pre>
31 |  */
32 | public class JavaEEVersion {
33 | 
34 |     public static final JavaEEVersion JAVA_EE_6 = new JavaEEVersion("javax", "javaee-api", "6.0");
35 |     public static final JavaEEVersion JAVA_EE_7 = new JavaEEVersion("javax", "javaee-api", "7.0");
36 |     public static final JavaEEVersion JAVA_EE_8 = new JavaEEVersion("javax", "javaee-api", "8.0");
37 |     public static final JavaEEVersion JAKARTA_EE_9 = new JavaEEVersion("jakarta.platform", "jakarta.jakartaee-api", "9.1.0");
38 |     public static final JavaEEVersion JAKARTA_EE_10 = new JavaEEVersion("jakarta.platform", "jakarta.jakartaee-api", "10.0.0");
39 |     public static final JavaEEVersion JAKARTA_EE_11 = new JavaEEVersion("jakarta.platform", "jakarta.jakartaee-api", "11.0.0");
40 | 
41 |     private final String groupId;
42 |     private final String artifactId;
43 |     private final String version;
44 | 
45 |     private JavaEEVersion(String groupId, String artifactId, String version) {
46 |         this.groupId = groupId;
47 |         this.artifactId = artifactId;
48 |         this.version = version;
49 |     }
50 | 
51 |     /**
52 |      * Web(Servlet仕様)のバージョン文字列から {@link JavaEEVersion} インスタンスを返す。
53 |      *
54 |      * <table>
55 |      *   <tr><th>Servlet</th><th>仕様</th><th>groupId</th><th>artifactId</th><th>version</th></tr>
56 |      *   <tr><td>3.0</td><td>Java EE 6</td><td>javax</td><td>javaee-api</td><td>6.0</td></tr>
57 |      *   <tr><td>3.1</td><td>Java EE 7</td><td>javax</td><td>javaee-api</td><td>7.0</td></tr>
58 |      *   <tr><td>4.0</td><td>Java EE 8</td><td>javax</td><td>javaee-api</td><td>8.0</td></tr>
59 |      *   <tr><td>5.0</td><td>Jakarta EE 9</td><td>jakarta.platform</td><td>jakarta.jakartaee-api</td><td>9.1.0</td></tr>
60 |      *   <tr><td>6.0</td><td>Jakarta EE 10</td><td>jakarta.platform</td><td>jakarta.jakartaee-api</td><td>10.0.0</td></tr>
61 |      *   <tr><td>6.1</td><td>Jakarta EE 11</td><td>jakarta.platform</td><td>jakarta.jakartaee-api</td><td>11.0.0</td></tr>
62 |      * </table>
63 |      *
64 |      * @param webVersion Servlet 仕様のバージョン（例: {@code "3.0"}）
65 |      * @return 対応する {@link JavaEEVersion} インスタンス
66 |      * @throws IllegalArgumentException 未知の webVersion が指定された場合
67 |      */
68 |     public static JavaEEVersion fromWebVersion(String webVersion) {
69 |         return switch (webVersion) {
70 |             case "3.0" -> JAVA_EE_6;
71 |             case "3.1" -> JAVA_EE_7;
72 |             case "4.0" -> JAVA_EE_8;
73 |             case "5.0" -> JAKARTA_EE_9;
74 |             case "6.0" -> JAKARTA_EE_10;
75 |             case "6.1" -> JAKARTA_EE_11;
76 |             default    -> throw new IllegalArgumentException("Unknown Servlet version: " + webVersion);
77 |         };
78 |     }
79 | 
80 |     /** {@code <groupId>} に出力するグループID。 */
81 |     public String getGroupId() {
82 |         return groupId;
83 |     }
84 | 
85 |     /** {@code <artifactId>} に出力するアーティファクトID。 */
86 |     public String getArtifactId() {
87 |         return artifactId;
88 |     }
89 | 
90 |     /** {@code <version>} に出力するバージョン。 */
91 |     public String getVersion() {
92 |         return version;
93 |     }
94 | }
